class Produkt3 {
  static RABAT = 0.1;
}

const produkt = new Produkt3();
console.log(produkt.RABAT); // undefined
// Pole statyczne nalezy WYLACZNIE do klasy, nie do zadnej konkretnej
// instancji - dostep mozliwy jest tylko przez nazwe klasy (Produkt3.RABAT),
// nigdy przez instancje (produkt.RABAT zawsze zwroci undefined).

class Waliduj {
  static jestEmail(tekst) {
    return tekst.includes("@");
  }
  static jestPelnoletni(wiek) {
    return wiek >= 18;
  }
}

console.log(Waliduj.jestEmail("test@test.pl")); // true
console.log(Waliduj.jestEmail("nieprawidlowy")); // false
console.log(Waliduj.jestPelnoletni(20)); // true
console.log(Waliduj.jestPelnoletni(15)); // false

class Identyfikator {
  static nastepneId = 1;
  static generuj() {
    const id = Identyfikator.nastepneId;
    Identyfikator.nastepneId++;
    return id;
  }
}

console.log(Identyfikator.generuj()); // 1
console.log(Identyfikator.generuj()); // 2
console.log(Identyfikator.generuj()); // 3

class Kolor {
  static CZERWONY = "#FF0000";
  static ZIELONY = "#00FF00";
  static NIEBIESKI = "#0000FF";
}

console.log(Kolor.CZERWONY); // "#FF0000"
console.log(Kolor.ZIELONY);  // "#00FF00"
console.log(Kolor.NIEBIESKI); // "#0000FF"

class Przyklad {
  wartosc = 42;
  metodaInstancji() {
    return this; // this === konkretna instancja, na ktorej metoda zostala wywolana
  }
  static metodaStatyczna() {
    return this; // this === sama klasa Przyklad, ZADNA instancja nie jest zwiazana
  }
}

const instancja = new Przyklad();
console.log(instancja.metodaInstancji() === instancja); // true
console.log(Przyklad.metodaStatyczna() === Przyklad);   // true
// W metodzie instancji this odnosi sie do KONKRETNEGO obiektu, na ktorym
// metoda zostala wywolana (instancja.metoda()). W metodzie statycznej
// this odnosi sie do SAMEJ KLASY, poniewaz metoda statyczna jest wywolywana
// na klasie (Klasa.metoda()), a nie na zadnej konkretnej instancji.

class Narzedzia {
  static suma(...liczby) {
    return liczby.reduce((s, x) => s + x, 0);
  }

  static srednia(...liczby) {
    return Narzedzia.suma(...liczby) / liczby.length;
  }
}

console.log(Narzedzia.suma(1, 2, 3)); // -> 6
console.log(Narzedzia.srednia(2, 4)); // -> 3

class Uzytkownik {
  static liczba = 0;

  constructor(nazwa) {
    this.nazwa = nazwa;
    Uzytkownik.liczba++;
  }

  static ile() {
    return Uzytkownik.liczba;
  }
}

new Uzytkownik("a");
new Uzytkownik("b");
new Uzytkownik("c");
console.log(Uzytkownik.ile()); // -> 3

class Baza {
  static create() {
    return new this();
  }
}

class Pochodna extends Baza {}

console.log(Pochodna.create() instanceof Pochodna); // -> true
console.log(Baza.create() instanceof Pochodna);     // -> false
console.log(Baza.create() instanceof Baza);         // -> true

class Konfiguracja {
  static instancja = null;

  static pobierz() {
    if (this.instancja === null) {
      this.instancja = new this();
    }
    return this.instancja;
  }
}

console.log(Konfiguracja.pobierz() === Konfiguracja.pobierz()); // -> true
console.log(new Konfiguracja() === Konfiguracja.pobierz());     // -> false (new tworzy nowy obiekt)

class Zwierze {
  static rejestr = [];

  constructor(imie) {
    this.imie = imie;
    Zwierze.rejestr.push(this);
  }

  static imiona() {
    return Zwierze.rejestr.map(z => z.imie);
  }
}

new Zwierze("Burek");
new Zwierze("Filemon");
console.log(Zwierze.imiona()); // -> ["Burek", "Filemon"]

class Walidator {
  static jestDodatnia(n) {
    return typeof n === "number" && n > 0;
  }

  static jestNiepusty(tekst) {
    return typeof tekst === "string" && tekst.trim() !== "";
  }

  static jestPelnoletni(wiek) {
    return wiek >= 18;
  }
}

console.log(Walidator.jestDodatnia(5), Walidator.jestDodatnia(-1));       // -> true false
console.log(Walidator.jestNiepusty("a"), Walidator.jestNiepusty("  "));   // -> true false
console.log(Walidator.jestPelnoletni(18), Walidator.jestPelnoletni(17));  // -> true false

class Konwerter {
  static naKelwiny(c) {
    return c + 273.15;
  }
}

console.log(Konwerter.naKelwiny(0));                      // -> 273.15
console.log(typeof new Konwerter().naKelwiny);            // -> "undefined"
console.log(new Konwerter().constructor.naKelwiny(0));    // -> 273.15
// Metoda statyczna nalezy do klasy - instancja jej nie ma, ale instancja.constructor wskazuje na klase.

class A {
  static f() {
    return this === A;
  }
}

console.log(A.f()); // -> true

const { f } = A;
console.log(f());   // -> false (this to undefined)
// Metoda statyczna jest zwyklą funkcją - po wyciagnieciu traci this.

class Podatek {
  static stawka = 0.23;
  static kwota = 100 * this.stawka;
}

console.log(Podatek.kwota); // -> 23

class Rejestr {
  static gotowy = false;

  static {
    console.log("inicjalizacja");
    Rejestr.gotowy = true;
  }
}

console.log(Rejestr.gotowy); // -> true
// Blok static wykonal sie raz, w chwili definicji klasy (przed pierwszym uzyciem).

class Baza {
  static opis() {
    return "baza";
  }
}

class Pochodna extends Baza {
  static opis() {
    return super.opis() + " -> pochodna";
  }
}

console.log(Pochodna.opis()); // -> "baza -> pochodna"

class Baza {
  static licznik = 0;
}
class Pochodna extends Baza {}

console.log(Object.hasOwn(Pochodna, "licznik")); // -> false (odziedziczone)
Pochodna.licznik++;
console.log(Baza.licznik);                        // -> 0
console.log(Pochodna.licznik);                    // -> 1
console.log(Object.hasOwn(Pochodna, "licznik")); // -> true
// Odczyt uzyl pola odziedziczonego z Baza, ale zapis stworzyl wlasne pole w Pochodna.

class Osoba {
  constructor(imie, wiek) {
    this.imie = imie;
    this.wiek = wiek;
  }

  static porownajWiek(a, b) {
    return a.wiek - b.wiek;
  }
}

const osoby = [new Osoba("Ala", 30), new Osoba("Jan", 20), new Osoba("Ola", 25)];
console.log(osoby.sort(Osoba.porownajWiek).map(o => o.imie)); // -> ["Jan", "Ola", "Ala"]

class Prostokat {
  constructor(szer, wys) {
    this.szer = szer;
    this.wys = wys;
  }

  static zTekstu(tekst) {
    const [s, w] = tekst.split("x").map(Number);
    return new Prostokat(s, w);
  }

  pole() {
    return this.szer * this.wys;
  }
}

console.log(Prostokat.zTekstu("3x4").pole()); // -> 12

class A {
  static s = 1;
  i = 2;
  m() {}
  static sm() {}
}

console.log(Object.keys(A));       // -> ["s"]  (statyczne pole klasy; metody nie sa wyliczalne)
console.log(Object.keys(new A())); // -> ["i"]  (pole instancji)

class Stan {
  static _licznik = 0;

  static get licznik() {
    return Stan._licznik;
  }

  static set licznik(v) {
    if (v < 0) throw new RangeError("ujemny");
    Stan._licznik = v;
  }
}

Stan.licznik = 5;
console.log(Stan.licznik); // -> 5

try {
  Stan.licznik = -1;
} catch (e) {
  console.log(e.name);     // -> "RangeError"
}

class Generator {
  static nastepny = 1;

  static id() {
    return Generator.nastepny++;
  }
}

console.log(Generator.id()); // -> 1
console.log(Generator.id()); // -> 2
console.log(Generator.id()); // -> 3

class Cena {
  static podatek = 0.23;

  static zPodatkiem(kwota) {
    return kwota * (1 + Cena.podatek);
  }

  constructor(kwota) {
    this.kwota = kwota;
  }

  brutto() {
    return Cena.zPodatkiem(this.kwota);
  }
}

console.log(new Cena(100).brutto()); // -> 123

class Baza {
  static nazwa = "baza";
  pokaz() {
    return [Baza.nazwa, this.constructor.nazwa];
  }
}

class Pochodna extends Baza {
  static nazwa = "pochodna";
}

console.log(new Baza().pokaz());     // -> ["baza", "baza"]
console.log(new Pochodna().pokaz()); // -> ["baza", "pochodna"]

class Grupa {
  static czlonkowie = [];
  lokalne = [];

  dodaj(x) {
    Grupa.czlonkowie.push(x);
    this.lokalne.push(x);
  }
}

const a = new Grupa();
const b = new Grupa();
a.dodaj("x");
b.dodaj("y");

console.log(Grupa.czlonkowie); // -> ["x", "y"]
console.log(a.lokalne);        // -> ["x"]
console.log(b.lokalne);        // -> ["y"]

class Prostokat {
  constructor(szer, wys) {
    this.szer = szer;
    this.wys = wys;
  }

  pole() {                       // instancyjna - potrzebuje danych konkretnego prostokata
    return this.szer * this.wys;
  }

  static porownajPola(a, b) {    // statyczna - dziala na dwoch obiektach, nie na jednym "this"
    return a.pole() - b.pole();
  }
}

console.log(Prostokat.porownajPola(new Prostokat(2, 3), new Prostokat(1, 4))); // -> 2

class Dzien {
  static pon = new Dzien("pon");
  static wt = new Dzien("wt");

  constructor(nazwa) {
    this.nazwa = nazwa;
  }

  toString() {
    return this.nazwa;
  }
}

console.log(String(Dzien.pon));                 // -> "pon"
console.log(Dzien.pon === Dzien.pon);           // -> true
console.log(Object.values(Dzien).map(String));  // -> ["pon", "wt"]

